void UCharacterMovementComponent::StartNewPhysics(float deltaTime, int32 Iterations)
{
	if ((deltaTime < MIN_TICK_TIME) || (Iterations >= MaxSimulationIterations) || !HasValidData())
	{
		return;
	}

	if (UpdatedComponent->IsSimulatingPhysics())
	{
		UE_LOGF(LogCharacterMovement, Log, "UCharacterMovementComponent::StartNewPhysics: UpdateComponent (%ls) is simulating physics - aborting.", *UpdatedComponent->GetPathName());
		return;
	}
